cd /work && python3 - <<'EOF'
import csv, json, re
from decimal import Decimal as D
d=json.load(open('deliverable/q1_close.json'))
print('json parses OK; top keys:', sorted(d.keys()))
rows=list(csv.DictReader(open('documents/bank_operating_q1.csv')))
by={'01':D('0'),'02':D('0'),'03':D('0')}
for r in rows: by[r['date'][5:7]]+=D(r['amount'])
err=0
for m in ('01','02','03'):
    mo=d['months'][m]
    ot=sum(D(str(v)) for v in mo['other'].values())
    tot=sum(D(str(mo[k])) for k in ('revenue','payroll','supplies','rent'))+ot
    if tot!=by[m]: err+=1; print('BUCKET ERR',m,tot,by[m])
    qt=d['q1_totals'][m]
    for k in ('revenue','payroll','supplies','rent'):
        if D(str(qt[k]))!=D(str(mo[k])): err+=1; print('QT ERR',m,k)
    if D(str(qt['other']))!=ot: err+=1; print('QT other ERR',m)
    for k,v in mo['other'].items():
        if D(str(qt['other_detail'][k]))!=D(str(v)): err+=1; print('QT detail ERR',m,k)
tq=d['q1_totals'].get('q1') or d['q1_totals'].get('total')
print('bucket+q1_totals errors:', err)
print('q1_totals top-level keys:', sorted(d['q1_totals'].keys()))
i=d['notes'].find('Every check matched')
print('fixed sentence in notes:', repr(d['notes'][i:i+56]))
# cross-reference sanity: every Q-id mentioned in notes/open_items exists in QUESTIONS.md
q=open('deliverable/QUESTIONS.md').read()
valid=set(re.findall(r'\| ([A-E]\d) \|', q))
for txt,label in ((d['notes'],'notes'),('\n'.join(d['open_items']),'open_items')):
    refs=set(re.findall(r'\b([A-E]\d)\b', txt))
    qrefs={x for x in refs if re.search(rf'(Q{0}|QUESTIONS[^)]*{0})'.format(x), txt)}  # only ids appearing as question refs
    dangling={x for x in refs if x not in valid and x not in {'A1','A2','A3','A4','A5','A6'} }
    print(label,'ids used:', sorted(refs), '| not in QUESTIONS (assumption-ids allowed):', sorted(dangling))
print('valid QUESTIONS ids:', sorted(valid))
EOF
echo ----; grep -rn "clearing 2 days\|clearing two days" deliverable/ ; grep -rn '"Dr. Harlow"' deliverable/ ; echo "(no output above = clean)"; grep -c "" deliverable/*.md

